document.addEventListener("DOMContentLoaded",function(){let n=[],r="";document.getElementById("form-treinadores").addEventListener("submit",function(e){e.preventDefault();var e=document.getElementById("nome-treinador").value,t=(n.unshift(e),"<tr>"),t=(t+=`<td>#${n.length}</td>`)+`<td>${e}</td>`+"</tr>";r+=t,document.getElementById("tabela-treinadores").innerHTML=r,console.log(n)}),document.getElementById("prosseguir").addEventListener("click",function(){0===n.length?(document.querySelector(".error").style.display="block",document.getElementById("nome-treinador").classList.add("input-error")):(document.querySelector(".error").style.display="none",document.getElementById("nome-treinador").classList.remove("input-error"))})});